"""Seating charts laid out as rows of text."""

from typing import List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError

Roster = Sequence[Student]

def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())

def _check(students: Roster, width: int) -> None:
    if width <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")

# ---
def seating_rows(students: Roster, width: int) -> List[str]:
    """One line per row, sorted by last name."""
    _check(students, width)
    ranked = sorted(students, key=_sort_key)
    return _build_lines(ranked, width)

def _row_line(chunk: List[Student], number: int) -> str:
    names = [item.display_name for item in chunk]
    return f"Row {number}: " + " | ".join(names)

def _build_lines(ranked: List[Student], width: int):
    lines = []
    for start in range(0, len(ranked), width):
        chunk = ranked[start:start + width]
        lines.append(_row_line(chunk, start // width + 1))
    return lines

