import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

WANT_ONE = "Row 1: Adler, Zoe | Dunmere, Piet"

def _make(last, first="Ann", number="1"):
    return Student(number, last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorts_and_splits_rows(self):
        people = [
            _make("Halloway", "Juno", "2"),
            _make("Dunmere", "Piet", "1"),
            _make("Adler", "Zoe", "3"),
        ]
        rows = seating_rows(people, 2)
        self.assertEqual(rows[0], WANT_ONE)
        self.assertEqual(rows[1], "Row 2: Halloway, Juno")

    def test_single_row_when_seats_exceed_students(self):
        people = [_make("Beta"), _make("Alpha")]
        rows = seating_rows(people, 10)
        self.assertEqual(len(rows), 1)
        self.assertTrue(rows[0].startswith("Row 1: Alpha"))

    def test_sort_ignores_case(self):
        people = [_make("zane"), _make("Young")]
        rows = seating_rows(people, 1)
        self.assertIn("Young", rows[0])

    def test_first_name_breaks_ties(self):
        people = [_make("Moss", "Bea")]
        people.append(_make("Moss", "Abe"))
        rows = seating_rows(people, 2)
        self.assertEqual(
            rows, ["Row 1: Moss, Abe | Moss, Bea"]
        )

    def test_bad_seat_count_raises(self):
        people = [_make("Moss")]
        for count in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(people, count)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)

if __name__ == "__main__":
    unittest.main()
